<?php require_admin();$students=$pdo->query("SELECT COUNT(*) FROM users WHERE role='student'")->fetchColumn();$cols=$pdo->query("SELECT COUNT(*) FROM colleges")->fetchColumn();$adm=$pdo->query("SELECT COUNT(*) FROM admissions")->fetchColumn();$dist=$pdo->query("SELECT COUNT(*) FROM admissions WHERE mode='Distance'")->fetchColumn();?><section class="wrap section"><span class="eyebrow">K2 OWNER CONSOLE</span><h1>Admin Dashboard</h1><div class="stats"><div><b><?=$students?></b><span>Students</span></div><div><b><?=$cols?></b><span>Institutions</span></div><div><b><?=$adm?></b><span>Admission records</span></div><div><b><?=$dist?></b><span>Distance records</span></div></div><div class="section-head"><h2>Admission & student records</h2><a class="btn btn-primary" href="<?=BASE_URL?>/actions/export.php">Export CSV</a></div><div class="table-wrap"><table><tr><th>Student</th><th>Email</th><th>Course</th><th>Institution</th><th>Mode</th><th>Status</th><th>Update</th></tr><?php $rows=$pdo->query("SELECT a.*,u.name student,u.email,c.name college FROM admissions a JOIN users u ON u.id=a.student_id LEFT JOIN colleges c ON c.id=a.college_id ORDER BY a.id DESC")->fetchAll(PDO::FETCH_ASSOC);foreach($rows as $r):?><tr><td><?=h($r['student'])?></td><td><?=h($r['email'])?></td><td><?=h($r['course'])?></td><td><?=h($r['college']??'—')?></td><td><?=h($r['mode'])?></td><td><form class="inline" method="post" action="<?=BASE_URL?>/actions/status.php"><input type="hidden" name="csrf" value="<?=csrf()?>"><input type="hidden" name="id" value="<?=$r['id']?>"><select name="status"><?php foreach(['Enquiry','Contacted','Counselling','Application','Documents Pending','Admitted','Closed'] as $v):?><option <?=$r['status']===$v?'selected':''?>><?=$v?></option><?php endforeach;?></select><button class="btn btn-small">Save</button></form></td><td><?=h(substr($r['created_at'],0,10))?></td></tr><?php endforeach;?></table><?php if(!$rows):?><p>No records submitted yet. Use the demo student login to create one.</p><?php endif;?></div><div class="panel"><h3>Demo data note</h3><p>All sample institution data is illustrative. This local prototype is not production-ready for real student personal documents or payments.</p></div></section>